import{_ as a,o as t,c as o,ae as i}from"./chunks/framework.vXWZTEWX.js";const m=JSON.parse('{"title":"ADR 039: Clickable Citations for Extracted Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"adr/039-clickable-citations.md","filePath":"adr/039-clickable-citations.md"}'),n={name:"adr/039-clickable-citations.md"};function s(r,e,c,d,l,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-039-clickable-citations-for-extracted-requirements" tabindex="-1">ADR 039: Clickable Citations for Extracted Requirements <a class="header-anchor" href="#adr-039-clickable-citations-for-extracted-requirements" aria-label="Permalink to &quot;ADR 039: Clickable Citations for Extracted Requirements&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2026-06-12</p><h2 id="context-and-problem-statement" tabindex="-1">Context and Problem Statement <a class="header-anchor" href="#context-and-problem-statement" aria-label="Permalink to &quot;Context and Problem Statement&quot;">​</a></h2><p>Users had no way to verify where each extracted requirement came from in the source PDF. The AI would extract requirements and show a page number, but the user couldn&#39;t see the original document text that justified the extraction. This made the AI a &quot;black box&quot; — users had to trust the output blindly.</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li>Users need to verify AI extraction accuracy against source documents</li><li>PDF text extraction via <code>pdf-parse</code> provides no bounding boxes or coordinates</li><li>Single AI call for page awareness (not one call per page) due to Gemini free tier rate limits</li><li>Must work for both standard PDFs (&lt; 15 pages) and large PDFs (chunked processing)</li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ol><li><strong>Page markers in prompt (chosen)</strong>: Embed <code>--- PAGE X ---</code> separators into the document text, ask the AI to return page number + source text fragment for each requirement</li><li><strong>Post-hoc text matching</strong>: Find each requirement in page texts after extraction — fragile, text rarely matches exactly</li><li><strong>Per-page chunked analysis</strong>: One AI call per page — precise but kills rate limits with large PDFs</li></ol><h2 id="decision-outcome" tabindex="-1">Decision Outcome <a class="header-anchor" href="#decision-outcome" aria-label="Permalink to &quot;Decision Outcome&quot;">​</a></h2><p>Chosen option: <strong>Page markers in prompt</strong>, because it balances precision with API cost — a single AI call produces structured data with page numbers and exact source fragments.</p><h3 id="key-implementation-details" tabindex="-1">Key Implementation Details <a class="header-anchor" href="#key-implementation-details" aria-label="Permalink to &quot;Key Implementation Details&quot;">​</a></h3><ul><li><code>chunking.ts</code> now builds chunk text with <code>--- PAGE X ---</code> markers instead of plain <code>\\n\\n</code> joins</li><li><code>AnalysisSchema</code> extended with <code>pageNumber</code> and <code>sourceText</code> fields in both <code>_analyze</code> and <code>analyzeChunk</code></li><li>Prompts instruct the AI to use page markers to determine the absolute page number for each requirement</li><li>Full page texts (<code>pageTexts: string[]</code>) preserved in <code>TenderAnalysis</code> response for the frontend citation viewer</li><li><code>processStandardPdf</code> calls <code>parsePages()</code> and builds page-marked text; falls back gracefully if <code>parsePages</code> fails</li><li>Frontend <code>CitationPreview</code> component: modal showing page text with highlighted source fragment</li></ul><h3 id="positive-consequences" tabindex="-1">Positive Consequences <a class="header-anchor" href="#positive-consequences" aria-label="Permalink to &quot;Positive Consequences&quot;">​</a></h3><ul><li>Users can click any &quot;Pág. X&quot; badge to see the exact document section where the requirement was found</li><li>AI has structured guidance for page numbers — more reliable than free-form extraction</li><li>Single-call approach keeps API costs low</li></ul><h3 id="negative-consequences" tabindex="-1">Negative Consequences <a class="header-anchor" href="#negative-consequences" aria-label="Permalink to &quot;Negative Consequences&quot;">​</a></h3><ul><li>AI can occasionally misidentify page numbers if page markers are ambiguous</li><li><code>parsePages()</code> is heuristic (splits by <code>--- Page N ---</code> markers from <code>pdf-parse</code>, or by character count) — may not always match the original PDF&#39;s pagination</li></ul><h2 id="files-changed" tabindex="-1">Files Changed <a class="header-anchor" href="#files-changed" aria-label="Permalink to &quot;Files Changed&quot;">​</a></h2><ul><li><code>backend/src/infrastructure/services/GeminiGenkitService.ts</code> — schema + prompt updates</li><li><code>backend/src/infrastructure/utils/chunking.ts</code> — page markers in chunk text</li><li><code>backend/src/application/use-cases/CreateTender.ts</code> — <code>processStandardPdf</code> calls <code>parsePages()</code>, preserves <code>pageTexts</code></li><li><code>backend/src/domain/entities/TenderAnalysis.ts</code> — added <code>pageTexts</code> field</li><li><code>frontend/src/types.ts</code> — added <code>pageTexts</code> to <code>TenderAnalysis</code></li><li><code>frontend/src/components/ui/CitationPreview.tsx</code> — new citation modal component</li><li><code>frontend/src/components/dashboard/AnalysisResults.tsx</code> — page number badge is now a clickable button</li><li><code>frontend/src/index.css</code> — added fade-in/scale-in animations for modal</li></ul>',18)])])}const p=a(n,[["render",s]]);export{m as __pageData,p as default};
